func (w *Worktree) resetWorktreeToTree(cfg *config.Config, toTree *object.Tree, idx *index.Index, files []string) error {
	filesMap := buildFilePathMap(files)

	fs, closeFS := w.reusableRootFS()
	defer closeFS()

	// Step 2: write files that are in the new index but missing or stale
	// in the worktree. We use diffStagingWithWorktree(reverse=true) which
	// gives Insert for "in index, not on disk" and Modify for "differs".
	// Delete means "on disk, not in index" = untracked → always skip.
	// Note: SkipWorktree entries are invisible to the merkletrie diff;
	// they are cleaned up in step 3 below.
	//
	// excludeIgnoredChanges=true engages the filesystem walker's
	// IgnoreScope so untracked entries inside gitignored directories are
	// pruned at enumeration time rather than walked and then dropped as
	// Delete actions. The observable result is unchanged because Delete
	// actions are skipped by the loop below; the matcher only avoids the
	// pointless lstat of every file under directories like node_modules.
	worktreeChanges, err := w.diffIndexWithWorktree(cfg, idx, true, true)
	if err != nil {
		return err
	}

	b := newIndexBuilder(idx)

	for _, ch := range worktreeChanges {
		a, err := ch.Action()
		if err != nil {
			return err
		}
		if a == merkletrie.Delete {
			// In the reverse diff, Delete means the file exists on disk but is
			// absent from the index node tree. SkipWorktree entries are marked
			// skip=true in the merkletrie and never appear here; they are removed
			// in step 3 below. A Delete action here therefore always means the
			// file is truly untracked — preserve it.
			continue
		}

		if len(files) > 0 {
			file := ch.To.String()
			if !inFiles(filesMap, file) {
				continue
			}
		}

		if err := w.checkoutChange(cfg, fs, ch, toTree, b); err != nil {
			return err
		}
	}

	// Step 3: remove tracked files that are SkipWorktree=true from disk.
	// diffStagingWithWorktree builds the index node tree with skip=true for
	// SkipWorktree entries, so they never appear as Delete actions in step 2.
	// git removes these files when the sparse-checkout contract excludes them.
	for _, e := range idx.Entries {
		if !e.SkipWorktree {
			continue
		}
		if len(files) > 0 && !inFiles(filesMap, e.Name) {
			continue
		}
		if _, statErr := fs.Lstat(e.Name); os.IsNotExist(statErr) {
			continue
		}
		if err := rmEntryAndDirsIfEmpty(fs, e.Name, e.Mode); err != nil {
			return err
		}
	}

	b.Write(idx)
	return w.r.Storer.SetIndex(idx)
}

// resetWorktree updates the worktree to match idx, the index a merge reset
// built, and then stores idx. files restricts the operation to the named
// paths; nil means all files.
//
// excludeIgnoredChanges is intentionally false here. The caller is
// MergeReset, and files contains paths that buildResetIndex just changed
// in idx. A tracked-but-gitignored path that was removed
// from the index in this same Reset is no longer in idxMap, so the
// noder's IgnoreScope would prune it from the walk and the Delete
// action needed to remove it from disk would never be emitted.
func (w *Worktree) resetWorktree(cfg *config.Config, t *object.Tree, idx *index.Index, files []string) error {
	changes, err := w.diffIndexWithWorktree(cfg, idx, true, false)
	if err != nil {
		return err
	}

	b := newIndexBuilder(idx)

	fs, closeFS := w.reusableRootFS()
	defer closeFS()

	filesMap := buildFilePathMap(files)
	for _, ch := range changes {
		if len(files) > 0 {
			file := ""
			if ch.From != nil {
				file = ch.From.String()
			} else if ch.To != nil {
				file = ch.To.String()
			}

			if file == "" {
				continue
			}

			contains := inFiles(filesMap, file)
			if !contains {
				continue
			}
		}

		if err := w.checkoutChange(cfg, fs, ch, t, b); err != nil {
			return err
		}
	}

	b.Write(idx)
	return w.r.Storer.SetIndex(idx)
}

func (w *Worktree) checkoutChange(cfg *config.Config, fs *worktreeFilesystem, ch merkletrie.Change, t *object.Tree, idx *indexBuilder) error {
	a, err := ch.Action()
	if err != nil {
		return err
	}

	var e *object.TreeEntry
	var name string
	var isSubmodule bool

	switch a {
	case merkletrie.Modify, merkletrie.Insert:
		name = ch.To.String()
		// FindEntry validates name via pathutil.ValidTreePath, so a
		// dangerous tree-derived path is refused at the lookup
		// boundary before we materialise anything.
		e, err = t.FindEntry(name)
		if err != nil {
			return err
		}

		isSubmodule = e.Mode == filemode.Submodule
	case merkletrie.Delete:
		// These names come from the filesystem-vs-index diff. Apply the
		// configured worktree gate. Tree-derived deletes use the same
		// helper in resetWorktreeToTree.
		//
		// resetWorktree is the only caller that reaches this, for a merge
		// reset. The mode would be the stored index entry's, but a merge
		// reset refuses a file or a directory standing at a tracked path
		// with ErrUnstagedChanges, so the shapes the mode separates never
		// reach here, and unknownMode removes the rest.
		return rmEntryAndDirsIfEmpty(fs, ch.From.String(), unknownMode)
	}

